    "question": "Which of the following degree sequences is graphic (i.e., can be realized by a simple undirected graph)?",
    "options": {
      "A": "(4, 4, 3, 2, 2, 1)",
      "B": "(5, 5, 4, 2, 2, 2)",
      "C": "(3, 3, 2, 2, 2, 1)",
      "D": "(6, 5, 4, 3, 2, 1)"
    },
    "correct_answer": "C",
    "explanation": "Using the Erdős–Gallai theorem, sequence (3,3,2,2,2,1) satisfies all inequalities and therefore is graphic, while the other three fail.",
    "difficulty": "Medium"
  },
  {
    "question": "In a connected graph G, a vertex v is called an articulation point if:",
    "options": {
      "A": "v has the highest degree in G.",
      "B": "Removing v and all incident edges disconnects the graph.",
      "C": "v lies on every cycle of G.",
      "D": "v is adjacent to all other vertices."
    },
    "correct_answer": "B",
    "explanation": "An articulation (or cut) vertex is one whose removal increases the number of connected components of the graph.",
    "difficulty": "Medium"
  },
  {
    "question": "What is the chromatic number of an odd cycle C₇?",
    "options": {
      "A": "2",
      "B": "3",
      "C": "4",
      "D": "5"
    },
    "correct_answer": "B",
    "explanation": "Any odd cycle requires three colors; two colors suffice only for even cycles.",
    "difficulty": "Medium"
  },
  {
    "question": "How many spanning trees does the complete graph K₅ have?",
    "options": {
      "A": "125",
      "B": "24",
      "C": "16",
      "D": "64"
    },
    "correct_answer": "A",
    "explanation": "Cayley’s formula gives n^{n‑2} spanning trees for Kₙ; for n = 5, 5^{3} = 125.",
    "difficulty": "Medium"
  },
  {
    "question": "If a simple graph G on n vertices is self‑complementary (isomorphic to its complement), which condition must n satisfy?",
    "options": {
      "A": "n ≡ 0 or 1 (mod 4)",
      "B": "n is even",
      "C": "n is a prime number",
      "D": "n is a multiple of 3"
    },
    "correct_answer": "A",
    "explanation": "A self‑complementary graph must have n(n‑1)/2 edges equal to its complement’s edge count, which forces n ≡ 0 or 1 (mod 4).",
    "difficulty": "Medium"
  }
